INSERT INTO parameters (param_id, name, category, description, data_type, benchmark_notes) VALUES
('program_name', 'Program Name', 'program_identity', 'Official consumer-facing name of the loyalty program.', 'string', 'Track renames (e.g., British Airways Executive Club → The British Airways Club, April 2025; Hilton HHonors → Hilton Honors, 2017; GrabRewards → GrabCoins).'),
('operator_company', 'Operator Company', 'program_identity', 'Legal entity or brand operating the program day-to-day.', 'string', 'May differ from brand (e.g., PAYBACK GmbH operated under Loyalty Partner GmbH within American Express Group).'),
('parent_company', 'Parent Company', 'program_identity', 'Ultimate parent/controlling company of the program operator.', 'string', 'Key for coalition and JV programs (e.g., Scene+ owned ~33.3% each by Scotiabank, Cineplex, Empire; flybuys 50/50 Coles–Wesfarmers).'),
('sector', 'Sector', 'program_identity', 'Primary industry sector of the program.', 'enum', 'Cross-sector programs (e.g., Amazon Prime, Walmart+) map to ''other'' or their dominant monetization sector.'),
('region', 'Primary Region', 'program_identity', 'Geographic footprint of the program.', 'enum', 'Use ''global'' only for genuinely multi-continent programs; otherwise pick the dominant operating region.'),
('launch_year', 'Launch Year', 'program_identity', 'Year the program launched (or year of current form after merger/rebrand).', 'integer', 'Reference points: AAdvantage 1981, Star Alliance 1997, Hilton HHonors 1987, Marriott Bonvoy merger 2019, Skywards 2001.'),
('program_archetype', 'Program Archetype', 'program_identity', 'Structural type of the loyalty program.', 'enum', 'Umbrex playbook archetypes: points, tiers, paid memberships, coalition, experiential; Open Loyalty adds account credits and gamification as primary frameworks.'),
('primary_objective', 'Primary Objective', 'program_identity', 'The single primary behavioral objective the program funds at launch.', 'enum', 'Loyalty Juggernaut: one primary objective at launch, others sequenced behind it; four behavioral types — frequency, basket size, retention, data/identity.'),
('tier_count', 'Tier Count', 'membership_tiers', 'Number of status tiers including entry level (excluding base non-status members if distinct).', 'integer', 'Industry norm is 3–5 tiers (Talon.One); Marriott Bonvoy has 5 elite tiers above base; Hilton Honors has 4 status levels.'),
('tier_names', 'Tier Names', 'membership_tiers', 'Ordered list of tier names from lowest to highest.', 'array_of_strings', 'Examples: Hilton (Member/Silver/Gold/Diamond), Qantas (Bronze/Silver/Gold/Platinum/Platinum One), AMC Stubs (Insider/Premiere/Premiere Go/A-List).'),
('tier_structure_type', 'Tier Structure Type', 'membership_tiers', 'Shape of the recognition layer: flat, tiered, or hybrid.', 'enum', 'Loyalty Juggernaut recognition layer has three broad shapes; hybrid combines tiers with transactional perks (e.g., AMC Stubs free tier + paid A-List subscription).'),
('qualification_metric', 'Qualification Metric', 'membership_tiers', 'Primary metric used to qualify for status.', 'array_of_enum', 'Shift to spend-based qualification is a notable trend (British Airways moved to spend-based tier points from April 2025: £7,500 Silver / £20,000 Gold annually).'),
('qualification_thresholds', 'Qualification Thresholds per Tier', 'membership_tiers', 'Threshold value required for each tier in the qualification metric''s unit.', 'object', 'Reference values: Marriott Silver 10 / Gold 25 / Platinum 50 / Titanium 75 / Ambassador 100 nights + $23,000 spend; Sephora VIB $350 / Rouge $1,000 annually; Qantas status credits 300/700/1400/3600.'),
('qualification_window', 'Qualification Window', 'membership_tiers', 'Period over which qualification metrics accumulate.', 'enum', 'ALDO uses rolling 12-month ($150/$300); many airlines use qualification year + 12-month status period.'),
('status_period_length', 'Status Period Length', 'membership_tiers', 'How long earned status lasts once qualified.', 'string', 'Common norm: 12-month status periods; benchmark against qualification window alignment.'),
('downgrade_policy', 'Downgrade Policy', 'membership_tiers', 'Rule governing status loss when requalification fails.', 'string', 'Design norm: maximum one-level downgrade (soft landing); e.g., Marriott Titanium with zero qualifying nights drops only to Platinum, not to base.'),
('grace_period', 'Status Grace / Extension Period', 'membership_tiers', 'Grace or extension mechanics offered on status (e.g., 90-day extensions, rollover nights).', 'string', 'Post-pandemic programs normalized status extensions and night rollovers; benchmark whether extensions are automatic or promotional.'),
('tier_membership_distribution', 'Tier Membership Distribution', 'membership_tiers', 'Share of active members in entry / mid / top tiers.', 'object', 'Design target: 60–70% entry, 20–30% mid, 5–10% top (Talon.One).'),
('top_tier_exclusivity', 'Top-Tier Exclusivity', 'membership_tiers', 'Percentage of total members in upper and top tiers.', 'object', 'Norm: upper tiers (silver/gold/platinum) <10% of base; top tier ≈0.5% of members (Open Loyalty).'),
('status_match_availability', 'Status Match Availability', 'membership_tiers', 'Whether the program offers status matches from competing programs, and under what terms.', 'string', 'Record match source list, documentation requirements, challenge vs instant match, and how long matched status lasts.'),
('base_earn_rate', 'Base Earn Rate', 'earning_structure', 'Primary earn rate for the core qualifying action (points/miles per currency unit, per mile, or per night).', 'string', 'Normalize to points per 1 local currency unit or % of spend for cross-program comparison.'),
('earn_currency', 'Earn Currency', 'earning_structure', 'Name and unit of the loyalty currency earned.', 'string', 'Miles (airlines), points (hotels/retail), coins (GrabCoins), status credits (Qantas, non-redeemable), ShowPoints (Audience Rewards).'),
('earn_metric_basis', 'Earn Metric Basis', 'earning_structure', 'Whether earning is based on distance flown, cabin, spend, nights, or transactions.', 'enum', 'BA''s 2025 move from distance/cabin tier points to spend-based tier points is an industry reference point.'),
('bonus_multiplier_structure', 'Bonus Multiplier Structure', 'earning_structure', 'How elite, promo, or partner multipliers stack on base earn.', 'string', 'Record whether multipliers stack multiplicatively or additively, and caps.'),
('partner_earning_network', 'Partner Earning Network', 'earning_structure', 'Size and type of partners that can earn the currency (transfer-in, direct earn, portals).', 'object', 'Examples: Chase Shop and Earn 1–15 pts/$ at 1,000+ stores; Nectar 14 member companies and 400+ online retailers (2010).'),
('promo_mechanics', 'Promo Mechanics', 'earning_structure', 'Standard promotional levers used (double-point days, challenges, streaks, gamification).', 'array_of_enum', 'T-Mobile Tuesdays is a partner-perks promo model; Starbucks Stars redesign (March 2026, Gold at 500 Stars) shows earn-threshold promos.'),
('welcome_bonus', 'Welcome / Enrollment Bonus', 'earning_structure', 'Bonus given on enrollment or first qualifying action.', 'string', 'Card examples: Barclaycard Avios free card 5,000 Avios on £1,000 spend in 3 months; Avios Plus 25,000 on £3,000.'),
('earn_caps', 'Earn Caps and Exclusions', 'earning_structure', 'Limits on earning (per transaction, per period, excluded categories).', 'string', 'Qantas charges a A$99.50 join fee — enrollment cost is itself an earn-side parameter.'),
('redemption_options', 'Redemption Options', 'redemption_options', 'Catalog of redemption categories available.', 'array_of_enum', 'Chase UR: travel, cash back, 200+ gift-card brands, transfers; Lidl Punkte redeems against streaming subscriptions (Disney+, BILD+).'),
('transfer_partners', 'Transfer Partners', 'redemption_options', 'External programs to which currency can be transferred, with ratios.', 'array_of_object', 'Amex MR transfers only to participating airline programs; Bilt transfers to ~19 airline programs and 7 hotel groups; record transfer ratio and transfer time.'),
('redemption_value_per_point', 'Redemption Value per Point', 'redemption_options', 'Effective cents-per-unit value (CPP/CPM) for typical redemptions.', 'number', 'Anchor: flybuys 2,000 points = A$10; PC Optimum 1,000 points = CA$1; AMC Stubs 5,000 points = $5 off.'),
('min_redemption_threshold', 'Minimum Redemption Threshold', 'redemption_options', 'Lowest balance required to redeem.', 'integer', 'PAYBACK redeems from 200 points; GrabCoins offsets from 50 coins.'),
('award_pricing_model', 'Award Pricing Model', 'redemption_options', 'How redemption prices are set.', 'enum', 'Dynamic pricing drives devaluation risk: award prices across 39 major airline/hotel programs rose ~37% 2015–2026 (~3.2%/yr), led by Delta SkyMiles +60% and Hilton Honors +55%.'),
('blackout_and_availability', 'Blackout Dates and Award Availability', 'redemption_options', 'Restrictions on redemption availability.', 'string', 'Record blackout dates, capacity controls, and whether partner awards are exempt.'),
('redemption_channels', 'Redemption Channels', 'redemption_options', 'Channels where redemption can occur.', 'array_of_enum', 'DBS points redeem via DBS PayLah! including NETS QR acceptance points — QR/offline redemption is a differentiator.'),
('expiration_policy', 'Expiration Policy', 'point_economics', 'Rules for currency expiry.', 'string', 'Reference trajectory: AAdvantage no expiration → 3 years (1989) → 18 months (2012) → 24 months (March 2022); Delta removed expiration 2011; United 2019; Cathay Asia Miles expire after 18 months of inactivity.'),
('devaluation_history', 'Devaluation History', 'point_economics', 'Record of earn-rate cuts, award-chart increases, or benefit reductions over time.', 'array_of_object', 'Track date, magnitude, and type; cross-check against benchmark index of ~3.2%/yr award inflation 2015–2026.'),
('earn_to_burn_ratio', 'Earn-to-Burn Ratio', 'point_economics', 'Points issued versus points redeemed over a period.', 'number', 'No widely published primary benchmark; proxy via issuer disclosures of deferral vs recognition (e.g., AAdvantage 2025: deferred $4.445B, recognized $3.935B).'),
('breakage_rate', 'Breakage Rate', 'point_economics', 'Estimated percentage of issued currency that will never be redeemed.', 'number', 'Delta recognizes breakage proportionally as remaining miles are redeemed; Marriott discloses a 1pp lower breakage estimate raises loyalty liability ~$50M; KPMG calls breakage a critical deferred-liability input.'),
('breakage_recognition_method', 'Breakage Recognition Method', 'point_economics', 'Accounting method used to recognize breakage revenue.', 'enum', 'Delta: proportional recognition with statistical models; Cathay actuary: Probability(Redemption) + Probability(Breakage) = 1 under IFRS 15.'),
('point_liability_balance', 'Point Liability Balance', 'point_economics', 'Carried loyalty program deferred revenue / liability.', 'number', 'Reference balances (FY2024/2025): Delta $8.8B; Marriott $7.519B; American Airlines $10.564B (YE2025).'),
('liability_sensitivity', 'Liability Sensitivity to Breakage', 'point_economics', 'Disclosed sensitivity of liability to a 1pp change in breakage estimate.', 'string', 'Marriott: −1pp breakage ≈ +$50M liability; 2024 estimate revisions reduced revenue and raised liability ~$72M.'),
('points_as_collateral', 'Points as Collateral / Financing', 'point_economics', 'Whether the program''s value has been pledged or securitized.', 'string', 'Delta SkyMiles valued at $6.5B and pledged as collateral in 2020 after a 78% decline in miles redeemed in H1 2020.'),
('enrolled_member_count', 'Enrolled Member Count', 'program_scale', 'Total enrolled members.', 'integer', 'Known figures: Hilton Honors 270M+ (official fact sheet, Oct 2026); Accor ALL 100M (2025); Qantas FF 18.9M (June 2026); AAdvantage 115M (April 2021); Amazon Prime ~220M (mid-2025).'),
('active_member_count', 'Active Member Count', 'program_scale', 'Members active within a defined period (12 months typical).', 'integer', 'Active/engaged ratio is a core health metric; Air Miles Netherlands reports 3.8M active.'),
('partner_network_size', 'Partner Network Size', 'program_scale', 'Count of earn/redemption partners (coalition members, transfer partners, co-brand merchants).', 'integer', 'PAYBACK: 30+ in-store partners across 22,000+ German stores and ~700 online shops; Rakuten Rewards US: 3,500+ stores.'),
('geographic_coverage', 'Geographic Coverage', 'program_scale', 'Countries/markets where the program operates.', 'string', 'Examples: Amazon Prime 28 countries; Tesco Clubcard UK/IE/CZ/SK/HU; Hertz ~160 countries.'),
('member_volume_share', 'Member Share of Volume', 'program_scale', 'Share of total business volume generated by members.', 'string', 'Marriott: loyalty members booked 72% of U.S. and 65% of global room nights in 2024.'),
('alliance_scale', 'Alliance / Network Scale', 'program_scale', 'Scale of alliance or multi-brand network the program plugs into.', 'string', 'Star Alliance: 26 members, ~1,300 airports, 195 countries, two-tier alliance rewards (Silver/Gold).'),
('mobile_app', 'Mobile App Availability', 'digital_presence', 'Whether a dedicated app exists and its core functions.', 'object', 'Record earn, redeem, card wallet, mobile order, push offers, digital membership card.'),
('website_portal', 'Website / Member Portal', 'digital_presence', 'Self-service web portal for balance, redemption, and profile.', 'boolean', 'Baseline requirement; benchmark depth (statement, partner marketplace, challenges hub).'),
('api_openness', 'API / Open Platform', 'digital_presence', 'Availability of public or partner APIs for earn/redemption integration.', 'enum', 'Open Loyalty benchmark includes data/integration as a readiness dimension; 28.6% name integration as top challenge.'),
('digital_wallet_integration', 'Digital Wallet Integration', 'digital_presence', 'Support for Apple/Google wallets, in-app barcode, QR redemption.', 'boolean', 'Table stakes in retail/dining; differentiator in emerging markets via QR (e.g., DBS/NETS QR).'),
('personalization_capability', 'Personalization and Data Capability', 'digital_presence', 'Ability to segment and personalize offers from first-party data.', 'enum', 'Open Loyalty Benchmark 2027 scores AI readiness as one of seven dimensions; 53.6% define success via retention/CLV.'),
('co_branded_cards', 'Co-branded Credit Cards', 'co_branded_partnerships', 'Co-branded card programs attached to the loyalty currency.', 'array_of_object', 'Record issuer, earn rate, annual fee, and elite-qualifying benefits; e.g., PC World Elite Mastercard earns 30 pts/$ at Loblaw affiliates.'),
('alliance_membership', 'Alliance / Coalition Membership', 'co_branded_partnerships', 'Airline alliance, hotel alliance, or coalition membership.', 'string', 'Alliances: Star Alliance, oneworld, SkyTeam; coalitions: PAYBACK, Air Miles, Scene+; hotel: GHA Discovery.'),
('cross_industry_partners', 'Cross-Industry Partnerships', 'co_branded_partnerships', 'Named partners outside the core sector (retail, fuel, streaming, dining).', 'array_of_string', 'Examples: Amazon Prime fuel discount at 7,500+ BP/Amoco/ampm; Walmart+ fuel at ExxonMobil/Murphy USA + Paramount+/Peacock + Burger King Royal Perks link.'),
('transfer_in_partners', 'Transfer-In Partners', 'co_branded_partnerships', 'Programs whose currency can be converted into this program''s currency.', 'array_of_string', 'Distinct from transfer-out; e.g., Barclaycard Avios sweeps monthly into The British Airways Club.'),
('lounge_access', 'Lounge Access Benefit', 'elite_perks', 'Lounge access by tier (own lounges, partner networks, guest allowances).', 'string', 'Core airline/hotel elite differentiator; record guest limits and third-party lounge programs (e.g., Priority Pass attach).'),
('upgrade_policy', 'Upgrade Policy', 'elite_perks', 'Complimentary or prioritized upgrades (cabin/room) by tier.', 'string', 'Record eligibility, confirmation windows, complimentary vs miles-based, and clear vs waitlist.'),
('priority_services', 'Priority Boarding / Check-in / Security', 'elite_perks', 'Priority processing benefits by tier.', 'string', 'Star Alliance Silver/Gold include priority boarding and upgrades as alliance-level incentives.'),
('late_checkout', 'Late Checkout / Guaranteed Availability', 'elite_perks', 'Late checkout, guaranteed room availability, and related hotel elite perks.', 'string', 'Record guaranteed 4pm checkout rights by tier and whether they are subject to availability.'),
('dedicated_support', 'Dedicated Support', 'elite_perks', 'Dedicated elite lines, ambassadors, or concierge.', 'string', 'Marriott Ambassador Elite: $23,000 + 100+ nights — top-tier service as a monetizable perk.'),
('experiential_rewards', 'Experiential / Event Rewards', 'elite_perks', 'Access to events, concerts, previews, and unique experiences.', 'string', 'ALL Accor Live Limitless positions experiences centrally; F1 membership (Aston Martin I/AM) is an experiential archetype.'),
('ancillary_fee_waivers', 'Fee Waivers and Service Perks', 'elite_perks', 'Baggage fee waivers, free award changes, breakfast, wifi, etc.', 'array_of_string', 'Bundle all cost-avoidance benefits; material to perceived value at mid tiers.'),
('revenue_model', 'Revenue Model', 'program_economics', 'How the program makes money.', 'array_of_enum', 'Qantas Frequent Flyer reported A$625M underlying EBIT in FY2025–26 — loyalty as a standalone profit center.'),
('membership_fee_structure', 'Membership Fee Structure', 'program_economics', 'Free vs paid tiers, join fees, and subscription pricing.', 'string', 'Reference: Qantas join fee A$99.50; Costco Executive $130/yr (Sept 2024); Walmart+ $98/yr; ALL Accor+ paid cards (Jan 2026); Barclaycard Avios Plus £20/month.'),
('profitability_disclosure', 'Profitability Disclosure', 'program_economics', 'Whether program-level profit/EBIT is publicly disclosed.', 'string', 'Qantas discloses loyalty EBIT; airlines disclose loyalty revenue and liability in 10-Ks even without full P&L.'),
('deferred_revenue_flow', 'Deferred Revenue Flow', 'program_economics', 'Annual deferral of revenue on points issued versus recognition on redemption/breakage.', 'object', 'AAdvantage 2025: deferred $4.445B, recognized $3.935B; Delta 2024: $7.1B loyalty revenue recognized ($3.8B travel awards + $3.3B other).'),
('audit_risk_profile', 'Audit Risk Profile', 'program_economics', 'Whether breakage/fair-value estimates are flagged as significant audit risks.', 'string', 'EY used an actuarial specialist to assess Delta''s mileage breakage estimate — a benchmark for estimate complexity.'),
('partner_economics', 'Partner Revenue Sharing', 'program_economics', 'How points economics are shared with coalition and transfer partners.', 'string', 'Record currency sale price to partners, breakage sharing, and redemption settlement terms.'),
('kpi_measurement_set', 'KPI Measurement Set', 'program_economics', 'Metrics used to judge program success.', 'array_of_enum', 'Umbrex KPI set: enrollment, activation, repeat rate, frequency, AOV, CLV, redemption, retention; 53.6% of surveyed firms use retention/CLV as the success definition.'),
('program_maturity_level', 'Program Maturity Level', 'program_economics', 'Maturity stage of the program against an industry model.', 'enum', 'Use a consistent maturity model (e.g., Umbrex 8-chapter playbook maturity model; Open Loyalty 7-dimension readiness score).'),
('regulatory_constraints', 'Regulatory Constraints', 'program_economics', 'Legal/regulatory limits affecting program design.', 'string', 'Reference: Norway banned domestic airline loyalty programs in 2002 to promote competition and lifted the ban in 2013; accounting standards (IFRS 15/ASC 606) govern liability.'),
('gamification_elements', 'Gamification Elements', 'earning_structure', 'Games, streaks, badges, challenges, and non-transactional engagement mechanics.', 'array_of_string', 'Gamification is one of Open Loyalty''s four primary frameworks; Club Canela awards 5 points per 5 minutes streamed (engagement earn).'),
('paid_membership_tier', 'Paid Membership Layer', 'program_economics', 'Whether a paid membership/subscription layer sits on top of the free program.', 'object', 'Examples: Amazon Prime (~220M), Costco (81.4M paid memberships, Feb 2026), Walmart+, Disney+, Uber One, AMC A-List, ALL Accor+, Instacart+.'),
('breakage_benefit_reversal', 'Breakage Reversal Risk', 'point_economics', 'History of reversing previously recognized breakage when redemption expectations change.', 'string', 'Southwest reversed $116M of prior breakage revenue in Q4 2024 for pandemic-era flight credits expected to be redeemed.');